<?php
require_once __DIR__ . "/../config/conexionBDD.php"; require_once __DIR__ . "/../logica/sesion.php"; requerirRol(['administrador']);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validarCSRF($_POST['csrf_token']??'')){http_response_code(400);exit('Token de seguridad inválido.');}$id=(int)($_POST['usuario_id']??0);$rol=$_POST['rol']??'usuario';$activo=(int)($_POST['activo']??1);if(in_array($rol,['administrador','supervisor','usuario'],true)&&$id!==(int)usuarioActual()['id']){$st=$conexion->prepare('UPDATE usuario SET rol=?,activo=? WHERE id=?');$st->bind_param('sii',$rol,$activo,$id);$st->execute();$st->close();}header('Location: perfiles.php');exit();}
$usuarios=$conexion->query('SELECT id,nombre_completo,nombre_usuario,rol,activo,fecha_registro FROM usuario ORDER BY fecha_registro DESC');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Perfiles de usuario</title><link rel="stylesheet" href="../css/estilos.css"></head><body><main class="contenedor"><p><a class="btn-secundario" href="../index.php">← Volver</a></p><h1>Perfiles y permisos de usuario</h1><p><strong>Administrador:</strong> gestiona perfiles y ve todos los registros. <strong>Supervisor:</strong> consulta contratos y riesgos de todos los usuarios. <strong>Usuario:</strong> consulta sus propios contratos y riesgos.</p><table class="tabla-listado"><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Activo</th><th>Guardar cambios</th></tr><?php while($u=$usuarios->fetch_assoc()){ ?><tr><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(tokenCSRF()) ?>"><input type="hidden" name="usuario_id" value="<?= (int)$u['id'] ?>"><td><?= htmlspecialchars($u['nombre_usuario']) ?></td><td><?= htmlspecialchars($u['nombre_completo']) ?></td><td><select name="rol"><option value="usuario" <?= $u['rol']==='usuario'?'selected':'' ?>>Usuario</option><option value="supervisor" <?= $u['rol']==='supervisor'?'selected':'' ?>>Supervisor</option><option value="administrador" <?= $u['rol']==='administrador'?'selected':'' ?>>Administrador</option></select></td><td><select name="activo"><option value="1" <?= $u['activo']?'selected':'' ?>>Activo</option><option value="0" <?= !$u['activo']?'selected':'' ?>>Inactivo</option></select></td><td><?php if((int)$u['id']!==(int)usuarioActual()['id']){ ?><button>Guardar</button><?php } else { ?>Perfil actual protegido<?php } ?></td></form></tr><?php } ?></table></main></body></html>